const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const appointmentId = clean(input.appointment_id);
const status = clean(input.status);

if (!appointmentId) {
  throw new Error('appointment_id es obligatorio');
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(appointmentId)) {
  throw new Error(
    `appointment_id no es un UUID válido: ${appointmentId}`
  );
}

const allowedStatuses = [
  'scheduled',
  'confirmed',
  'cancelled',
  'completed',
  'no_show'
];

if (!status) {
  throw new Error('status es obligatorio');
}

if (!allowedStatuses.includes(status)) {
  throw new Error(
    `status inválido: ${status}`
  );
}

return [
  {
    json: {
      appointment_id: appointmentId,

      update: {
        status
      }
    }
  }
];

const appointment = $json.data;

if (!appointment?.id) {
  throw new Error(
    'Directus no devolvió appointment.id'
  );
}

return [
  {
    json: {
      status: 'updated',
      appointment
    }
  }
];
